export class Path {
    path;
    constructor(path = []){
        this.path = path;
    }
    of = (element)=>{
        return new Path([
            ...this.path,
            element
        ]);
    };
    isRoot = ()=>{
        return this.path.length === 0;
    };
    last = ()=>{
        return this.path[this.path.length - 1];
    };
    toArray = ()=>{
        return this.path;
    };
}
